func TestSanitizeProfileID(t *testing.T) {
	cases := map[string]string{
		"pg-meta":       "pg-meta",
		"a/b\\c":        "a_b_c",
		"../etc/passwd": ".._etc_passwd",
		"":              "_",
		"..":            "_",
	}
	for in, want := range cases {
		if got := sanitizeProfileID(in); got != want {
			t.Errorf("sanitizeProfileID(%q)=%q want %q", in, got, want)
