func (c *Collector) DiscoverSchemas(ctx context.Context, sourceID string) ([]DatabaseAsset, error) {
	dialect, err := c.q.ProfileDialect(ctx, sourceID)
	if err != nil {
		return nil, err
	}
	var query string
	switch dialect {
	case "postgres":
		query = `SELECT schema_name FROM information_schema.schemata ORDER BY schema_name`
	case "mysql", "mariadb":
		query = `SELECT schema_name FROM information_schema.schemata ORDER BY schema_name`
	case "oracle":
		query = `SELECT DISTINCT owner AS "schema" FROM all_objects WHERE object_type IN ('TABLE','VIEW','MATERIALIZED VIEW') ORDER BY owner`
	default:
		return nil, fmt.Errorf("unsupported dialect: %s", dialect)
	}
	rows, err := c.q.SystemQuery(ctx, sourceID, query)
	if err != nil {
		return nil, err
	}
	var out []DatabaseAsset
	for _, r := range rows {
		s := asString(r["schema_name"])
		if dialect == "oracle" {
			s = asString(r["schema"])
		}
		if s == "" || systemSchemas[strings.ToLower(s)] {
			continue
		}
		out = append(out, DatabaseAsset{Schema: s, Kind: "schema"})
	}
	return out, nil
}

