// MaskedRef hides the sensitive part of a password_ref for API responses.
func MaskedRef(ref string) string {
	scheme, err := parsePasswordRef(ref)
	if err != nil {
		return "(invalid)"
	}
	if scheme == "plain" {
		return "plain:****"
	}
	return ref // env:NAME / file:PATH are pointers, not secrets
}

