// default_transaction_read_only=on is enforced (GO-SQL read-only backstop).
func (d postgresDialect) BuildDSN(p Profile, password string) (string, error) {
	cs := strings.TrimSpace(p.ConnectString)
	var u *url.URL
	switch {
	case strings.HasPrefix(cs, "postgres://") || strings.HasPrefix(cs, "postgresql://"):
		parsed, err := url.Parse(cs)
		if err != nil {
			return "", fmt.Errorf("invalid postgres URL: %w", err)
		}
		u = parsed
	default:
		m := connectStringRE.FindStringSubmatch(cs)
		if m == nil {
			return "", fmt.Errorf("connect_string must be host:port/dbname or a postgres:// URL")
		}
		u = &url.URL{Scheme: "postgres", Host: m[1] + ":" + m[2], Path: "/" + m[3]}
		if m[4] != "" {
			u.RawQuery = m[4]
		}
	}
	u.User = url.UserPassword(p.Username, password)
	q := u.Query()
	q.Set("default_transaction_read_only", "on")
	if q.Get("connect_timeout") == "" {
		q.Set("connect_timeout", "5")
	}
	u.RawQuery = q.Encode()
	return u.String(), nil
}

func (postgresDialect) WrapLimit(sqlText string, limit int) string {
	return fmt.Sprintf("SELECT * FROM (%s) AS sqlon_q LIMIT %d", trimSQL(sqlText), limit)

	return m.store.ListAllProfiles(ctx)
}

// Invalidate closes and forgets a profile's pool (after CRUD changes).
func (m *Manager) Invalidate(profileID string) {
	m.mu.Lock()
	defer m.mu.Unlock()
	if p, ok := m.pools[profileID]; ok {
		_ = p.db.Close()
		delete(m.pools, profileID)
	}
	delete(m.brk, profileID)
	m.invalidateInventory(profileID)
}

// Close shuts down every pool (GO-RUN-008 graceful shutdown).
func (m *Manager) Close() {
	m.mu.Lock()
		return 0, err
	}
	if err := EnforceOracleLicense(p, sqlText); err != nil {
		return 0, err
	}
	if err := m.breakerCheck(p.ID); err != nil {
		return 0, err
	}
	db, err := m.db(p)
	if err != nil {
		m.breakerRecord(p.ID, err)
		return 0, err
	}
	qctx, cancel := context.WithTimeout(ctx, durationSeconds(p.Policy.QueryTimeoutSeconds))
	defer cancel()

